                  cloids) external override onlyCloser {
              function closeOrdersByCloid(uint32[] calldata assets, uint128[] calldata
                  cloids) external override onlyCloser {
                  require(assets.length /= cloids.length, "Length Mismatch!");
                  for (uint256 i = 0; i < assets.length; i++) {
