 @>       position.open = false;
          ...
 @>       // If user passes 0, use full Morpho collateral (default behavior)
 @>       // If non-zero, validate it doesn't exceed actual collateral
 @>       uint256 collateralToWithdraw = amountCollateral == 0
              ? morphoPosition.collateral
              : amountCollateral;

